export const register: Register = (on, options) => {
  installStore(on);
  installBand(on);
  installSession(on);
  installRewind(on);
  installRoster(on);
  installFailure(on);
  installStop(on);
  installStatus(on);
  installCommand(on, options);
  installDump(on);
  installLifecycle(on);
  installGuidance(on);
  installAgents(on);
  installFeed(on);
  installReview(on);
  installLog(on);
  installNote(on);
  installSubagents(on);
  installDelivery(on, options);
  installTools(on);
};

